const modules=[
['WORKSPACE','command-center','⌂','Command Center'],['BRAND','brand-center','◇','Brand Center'],['BRAND','brand-brain','◉','Brand Brain'],['PLAN','strategy','✦','AI Strategy'],['PLAN','campaigns','◎','Campaigns'],['CREATE','content','✎','AI Content Studio'],['CREATE','creative','▣','AI Creative Studio'],['CREATE','assets','▧','Asset Library'],['PUBLISH','approvals','✓','Team & Approvals'],['PUBLISH','calendar','□','Social Calendar'],['PUBLISH','social','↗','Social Media Hub'],['INTELLIGENCE','analytics','⌁','Smart Analytics'],['INTELLIGENCE','intelligence','◈','Marketing Intelligence'],['INTELLIGENCE','copilot','✣','AI Copilot'],['OPERATE','automations','⚡','Automations'],['OPERATE','notifications','●','Notifications'],['OPERATE','activity','≡','Activity Log'],['ACCOUNT','settings','⚙','Settings'],['ACCOUNT','billing','$','Billing & Usage']
];
const state={page:'command-center',brand:'Acme Coffee',media:true,generated:false,caption:'A slower morning, made better. Freshly roasted coffee, thoughtful details, and a space designed for your everyday pause. #AcmeCoffee #RiyadhCoffee',credits:8420};
const nav=document.getElementById('nav'),content=document.getElementById('content'),title=document.getElementById('page-title'),eyebrow=document.getElementById('page-eyebrow'),modal=document.getElementById('modal-backdrop'),modalTitle=document.getElementById('modal-title'),modalBody=document.getElementById('modal-body'),toast=document.getElementById('toast');
function esc(v){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function buildNav(){let g='';nav.innerHTML=modules.map(([group,id,icon,label])=>{let h='';if(group!==g){g=group;h=`<div class="nav-group">${group}</div>`;}return `${h}<button class="nav-item" data-page="${id}"><span class="icon">${icon}</span><span>${label}</span></button>`}).join('');}
function head(name,desc,buttons=''){return `<div class="page-head"><div><h2>${name}</h2><p>${desc}</p></div><div class="actions">${buttons}</div></div>`}
function btn(label,action,kind='ghost'){return `<button class="${kind}" data-action="${action}">${label}</button>`}
function badge(text,tone=''){return `<span class="badge ${tone}">${text}</span>`}
function metric(label,value,delta=''){return `<div class="card metric"><span>${label}</span><strong>${value}</strong>${delta?`<small class="${delta.startsWith('+')?'positive':delta.startsWith('-')?'negative':''}">${delta}</small>`:''}</div>`}
function toastMsg(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>toast.classList.remove('show'),2200)}
function openModal(name,body){modalTitle.textContent=name;modalBody.innerHTML=body;modal.hidden=false}
function closeModal(){modal.hidden=true}
function cycleModal(){openModal('The complete customer cycle',`<div class="cycle">${[['1','Set up','Create workspace, brand identity, Brand Brain, assets and social connections.'],['2','Plan','Use AI Strategy, campaigns and intelligence to decide what to say and where.'],['3','Create','Create copy in AI Content Studio and visuals in AI Creative Studio or choose existing Assets.'],['4','Review','Preview every channel variant, submit for approval and resolve requested changes.'],['5','Schedule','Place approved content on the Social Calendar with local date/time.'],['6','Publish','Publishing worker validates approval, connection and platform rules, then sends once.'],['7','Measure','Analytics ingests platform metrics and shows trends, top posts and comparisons.'],['8','Learn','Insights and Copilot turn evidence into recommendations and Brand Brain learning candidates.'],['9','Repeat','The next strategy and content generation starts with better brand knowledge and performance context.']].map(x=>`<div class="cycle-step"><b>${x[0]}</b><div><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}</div>`)}
function commandCenter(){return head('Command Center','The customer’s daily operating view: what needs attention, what is publishing, current performance and AI usage.',btn('＋ Create post','new-post','primary')+btn('View full cycle','show-cycle'))+`<div class="grid four">${metric('Needs approval','3','2 urgent')}${metric('Publishing today','5','Next 14:30')}${metric('AI credits','8,420','62% remaining')}${metric('Engagement','6.8%','+14.2% vs prior')}</div><div class="grid two"><div class="card"><div class="section-title"><h3>Needs your attention</h3></div><table><tr><th>Item</th><th>Status</th><th>Action</th></tr><tr><td>Weekend coffee carousel</td><td>${badge('Approval','amber')}</td><td>${btn('Review','go-approvals','mini-btn')}</td></tr><tr><td>Instagram connection</td><td>${badge('Healthy','green')}</td><td>${btn('Manage','go-social','mini-btn')}</td></tr><tr><td>AI credits</td><td>${badge('62% left','purple')}</td><td>${btn('Usage','go-billing','mini-btn')}</td></tr></table></div><div class="card"><div class="section-title"><h3>Today</h3></div><div class="timeline"><div class="timeline-item"><strong>10:00 · Instagram Reel</strong><p>Published successfully · 1.2k reach so far</p></div><div class="timeline-item"><strong>14:30 · LinkedIn post</strong><p>Approved and scheduled</p></div><div class="timeline-item"><strong>18:00 · Instagram carousel</strong><p>Waiting for approval</p></div></div></div></div><div class="section-title"><h3>Workspace setup</h3>${badge('82% complete','purple')}</div><div class="card"><div class="progress"><span style="width:82%"></span></div><p>Brand identity ✓ · Brand Brain ✓ · Assets ✓ · Social accounts ✓ · Billing ✓ · Complete approval policy and analytics connection settings.</p><div class="actions">${btn('Continue setup','go-settings','primary')}</div></div>`}
function brandCenter(){return head('Brand Center','The structured identity of the selected brand. Visual identity and core brand facts live here; deeper knowledge lives in Brand Brain.',btn('Save changes','save-brand','primary'))+`<div class="grid two"><div class="card"><h3>Brand identity</h3><div class="form-grid"><div class="field"><label>Brand name</label><input value="${esc(state.brand)}"></div><div class="field"><label>Handle</label><input value="@acme.coffee"></div><div class="field full"><label>Brand description</label><textarea>Specialty coffee for everyday rituals, built around warm hospitality and thoughtful craft.</textarea></div><div class="field"><label>Primary color</label><input value="#3A274F"></div><div class="field"><label>Accent color</label><input value="#D9B66F"></div><div class="field"><label>Primary language</label><select><option>Arabic + English</option></select></div><div class="field"><label>Default timezone</label><select><option>Asia/Riyadh</option></select></div></div></div><div class="card"><h3>Logo & visual system</h3><div class="creative-stage"><div><strong>ACME</strong><p>Primary logo · SVG</p>${btn('Replace logo','simulate')}</div></div><div class="section-title"><h3>Quick links</h3></div><div class="actions">${btn('Open Brand Brain','go-brain')}${btn('Open Assets','go-assets')}${btn('Brand guidelines','simulate')}</div></div></div>`}
function brainCard(name,count,text){return `<div class="card"><div class="section-title"><h3>${name}</h3>${badge(count+' items','purple')}</div><p>${text}</p>${btn('View & edit','edit-brain','mini-btn')}</div>`}
function brandBrain(){return head('Brand Brain','The knowledge system grounding every AI output: audience, offers, tone, proof, rules, FAQs, competitors and uploaded documents.',btn('＋ Add knowledge','add-knowledge','primary')+btn('Upload document','upload-doc'))+`<div class="grid four">${metric('Knowledge completeness','91%','Ready for AI')}${metric('Approved items','46')}${metric('Documents','8')}${metric('Learning candidates','3','From analytics')}</div><div class="section-title"><h3>Knowledge areas</h3>${badge('Grounding active','green')}</div><div class="grid three">${brainCard('Audience','6','Personas, needs, locations, objections and buying context.')}${brainCard('Voice & tone','5','Brand personality, writing style, Arabic dialect, do/don’t rules.')}${brainCard('Products & offers','11','Services, offers, pricing context and approved claims.')}${brainCard('Proof points','7','Credentials, differentiators, evidence and trusted facts.')}${brainCard('FAQs & glossary','9','Approved answers and terminology the AI should use consistently.')}${brainCard('Competitors','8','Known competitors and positioning context — not unsupported claims.')}</div><div class="section-title"><h3>Learning candidates</h3></div><div class="card"><table><tr><th>Candidate</th><th>Source</th><th>Action</th></tr><tr><td>Educational carousels consistently outperform promotional posts.</td><td>Analytics insight</td><td class="row-actions">${btn('Review','review-learning','mini-btn')}${btn('Dismiss','simulate','mini-btn')}</td></tr><tr><td>Audience engages more with bilingual captions on weekends.</td><td>Analytics insight</td><td class="row-actions">${btn('Review','review-learning','mini-btn')}</td></tr></table></div>`}
function strategy(){return head('AI Strategy','Turns Brand Brain, historical performance and current objectives into an evidence-grounded marketing direction.',btn('Generate / refresh strategy','generate-strategy','primary')+btn('Monthly plan','monthly-plan'))+`<div class="grid three">${metric('Strategy status','Active','Updated 4d ago')}${metric('Content pillars','5')}${metric('Plan coverage','4 weeks','October')}</div><div class="grid two"><div class="card"><h3>Strategic direction</h3><p><b>Goal:</b> increase repeat visits and strengthen the brand as a daily specialty-coffee ritual.</p><p><b>Primary audience:</b> urban professionals and students seeking quality without formality.</p><p><b>Channel focus:</b> Instagram for discovery, TikTok for reach, LinkedIn for employer/community stories.</p>${btn('Edit objectives','simulate')}</div><div class="card"><h3>Content pillars</h3><table><tr><td>Education & craft</td><td>30%</td></tr><tr><td>Product & menu</td><td>25%</td></tr><tr><td>Space & experience</td><td>20%</td></tr><tr><td>Community</td><td>15%</td></tr><tr><td>Brand stories</td><td>10%</td></tr></table>${btn('Regenerate pillars','simulate')}</div></div><div class="section-title"><h3>Recommended next actions</h3></div><div class="grid three"><div class="card"><h3>Launch October campaign</h3><p>Theme generated from current strategy and seasonal context.</p>${btn('Create campaign','go-campaigns','primary')}</div><div class="card"><h3>Fill content gap</h3><p>Only 8% of recent content covers coffee education vs 30% strategy target.</p>${btn('Generate ideas','simulate')}</div><div class="card"><h3>Review competitor context</h3><p>Three positioning notes have changed since the last review.</p>${btn('Open intelligence','go-intelligence')}</div></div>`}
function campaigns(){return head('Campaigns','Groups goals, dates, channels, content and performance into one marketing initiative.',btn('＋ New campaign','new-campaign','primary'))+`<div class="card"><table><tr><th>Campaign</th><th>Dates</th><th>Channels</th><th>Content</th><th>Status</th><th></th></tr><tr><td><b>October Rituals</b><br><small>Drive repeat visits</small></td><td>1–31 Oct</td><td>IG · TikTok · FB</td><td>12 items</td><td>${badge('Active','green')}</td><td>${btn('Open','open-campaign','mini-btn')}</td></tr><tr><td><b>New Branch Opening</b></td><td>10–24 Sep</td><td>IG · TikTok · LinkedIn</td><td>9 items</td><td>${badge('Reporting','purple')}</td><td>${btn('Report','go-analytics','mini-btn')}</td></tr><tr><td><b>Saudi National Day</b></td><td>20–24 Sep</td><td>IG · FB</td><td>6 items</td><td>${badge('Completed')}</td><td>${btn('View','open-campaign','mini-btn')}</td></tr></table></div><div class="section-title"><h3>Campaign workflow</h3></div><div class="card"><div class="kpi-strip"><span class="pill">Goal</span><span>→</span><span class="pill">Audience</span><span>→</span><span class="pill">Channels</span><span>→</span><span class="pill">Content plan</span><span>→</span><span class="pill">Create & approve</span><span>→</span><span class="pill">Publish</span><span>→</span><span class="pill">Campaign analytics</span></div></div>`}
function contentStudio(){return head('AI Content Studio','Create one content item with channel-specific variants. AI copy is grounded in Brand Brain; media can be uploaded, selected from Assets or created in Creative Studio.',btn('Save draft','save-draft')+btn('Submit for review','submit-review','primary'))+`<div class="composer"><div class="card"><h3>Post brief</h3><div class="field"><label>Channels</label><div class="kpi-strip"><button class="pill">✓ Instagram</button><button class="pill">✓ Facebook</button><button class="pill">LinkedIn</button><button class="pill">TikTok</button></div></div><div class="field"><label>Brief</label><textarea id="brief">Create a post about the calm evening atmosphere in our Riyadh branch. Make it warm, premium and not overly promotional.</textarea></div><div class="form-grid"><div class="field"><label>Language</label><select><option>English</option><option>Arabic</option><option>Arabic + English</option></select></div><div class="field"><label>Content type</label><select><option>Post</option><option>Carousel</option><option>Reel caption</option><option>Story</option></select></div></div><div class="section-title"><h3>Media</h3><span class="helper">Upload, Assets or AI Creative</span></div><div class="media-strip" id="media-strip">${state.media?'<div class="media-tile">☕<button data-action="remove-media">×</button></div>':''}<button class="add-media" data-action="add-media">＋<small>Add media</small></button></div><div class="section-title"><h3>AI generation</h3></div><div class="actions">${btn('Estimate credits','estimate')}${btn('Generate copy','generate-copy','primary')}</div></div><div class="card"><div class="tabs"><button class="tab active">Instagram</button><button class="tab">Facebook</button></div><h3>Generated variant</h3><div class="field"><label>Caption</label><textarea id="caption">${esc(state.caption)}</textarea></div><div class="actions">${btn('Shorter','shorter','mini-btn')}${btn('Change tone','tone','mini-btn')}${btn('Hashtags','hashtags','mini-btn')}${btn('Translate','translate','mini-btn')}</div><div class="section-title"><h3>Live preview</h3></div><div class="social-preview"><div class="preview-head"><span class="preview-avatar"></span><b>acme.coffee</b></div>${state.media?'<div class="preview-media">EVENING<br>RITUALS</div>':'<div class="preview-media" style="background:#efedf2;color:#777">No media selected</div>'}<div class="preview-copy">${esc(state.caption)}</div></div></div><div class="card copilot-box"><h3>Copilot</h3><p>Context-aware help for this post.</p><div class="chat"><div class="bubble ai">I can tighten the caption, check it against Brand Brain, suggest a better hook or prepare it for another channel.</div><div class="bubble user">Does this sound too promotional?</div><div class="bubble ai">No. It stays experience-led and avoids a hard sales CTA, which matches the brand’s do/don’t rules.</div></div><div class="chat-compose"><input placeholder="Ask about this post…"><button class="primary" data-action="copilot-send">Send</button></div></div></div>`}
function creative(){return head('AI Creative Studio','Generate on-brand images and adapt approved assets to platform formats. This is not a full graphic design editor; it focuses on AI generation and templated adaptation.',btn('Generate visual','generate-visual','primary'))+`<div class="grid two"><div class="card"><h3>Create visual</h3><div class="field"><label>Prompt / creative brief</label><textarea>Warm cinematic evening inside a premium specialty coffee shop, natural people in the background, focus on a handcrafted latte, realistic editorial photography.</textarea></div><div class="form-grid"><div class="field"><label>Format</label><select><option>Instagram 4:5</option><option>Square 1:1</option><option>Story / Reel 9:16</option><option>LinkedIn 1.91:1</option></select></div><div class="field"><label>Brand style</label><select><option>Use Acme Coffee identity</option></select></div></div><div class="field"><label>Reference assets</label><div class="media-strip"><div class="media-tile">☕</div><div class="media-tile">A</div><button class="add-media" data-action="choose-assets">＋<small>Assets</small></button></div></div><div class="actions">${btn('Estimate credits','estimate-creative')}${btn('Generate 4 options','generate-visual','primary')}</div></div><div class="card"><h3>Generated result</h3><div class="creative-stage" id="creative-result"><div>${state.generated?'<strong>ACME EVENING</strong><p>AI-generated asset · 1080×1350 · saved provenance</p>':'<strong>✦</strong><p>Your generated image options will appear here.</p>'}</div></div>${state.generated?`<div class="actions" style="margin-top:12px">${btn('Save to Assets','save-generated','primary')}${btn('Use in post','use-generated')}${btn('Create sizes','resize-generated')}</div>`:''}</div></div><div class="section-title"><h3>How generated creatives enter the platform</h3></div><div class="card"><div class="kpi-strip"><span class="pill">AI Creative Studio</span><span>→</span><span class="pill">Generated Asset</span><span>→</span><span class="pill">Asset Library</span><span>→</span><span class="pill">Content Studio</span><span>→</span><span class="pill">Preview / Approval</span><span>→</span><span class="pill">Publish</span></div></div>`}
function assets(){return head('Asset Library','Central media library for uploaded and AI-generated brand assets, with folders, tags, versions, rights/expiry and usage tracking.',btn('Upload files','upload-asset','primary')+btn('Create with AI','go-creative'))+`<div class="kpi-strip" style="margin-bottom:14px"><button class="pill">All assets 128</button><button class="pill">Photos 74</button><button class="pill">Videos 18</button><button class="pill">Logos 9</button><button class="pill">AI generated 27</button></div><div class="asset-grid">${[['☕','Evening-latte.jpg','Photo · Clean'],['🏪','riyadh-branch.jpg','Photo · Clean'],['A','logo-primary.svg','Logo · Current'],['✦','ai-evening-01.jpg','AI generated'],['▣','national-day-01.jpg','Campaign creative'],['🎬','barista-reel.mp4','Video · Clean'],['☕','beans-closeup.jpg','Photo · Clean'],['✦','ai-product-02.jpg','AI generated'],['A','brand-pattern.png','Brand element'],['▧','menu-cover.jpg','Product']].map(x=>`<div class="asset"><div class="asset-art">${x[0]}</div><div class="asset-body"><strong>${x[1]}</strong><small>${x[2]}</small><div class="row-actions" style="margin-top:7px">${btn('Use','use-asset','mini-btn')}${btn('•••','asset-menu','mini-btn')}</div></div></div>`).join('')}</div>`}
function approvals(){return head('Team & Approvals','Members, roles and the content approval queue. Approval policy is brand-scoped and self-approval is denied by default.',btn('Invite member','invite-member','primary')+btn('Approval policy','approval-policy'))+`<div class="grid two"><div class="card"><h3>Approval queue</h3><table><tr><th>Content</th><th>Creator</th><th>Status</th><th></th></tr><tr><td>Weekend coffee carousel</td><td>Sara</td><td>${badge('Needs review','amber')}</td><td>${btn('Review','review-post','mini-btn')}</td></tr><tr><td>Branch story</td><td>Omar</td><td>${badge('Changes requested','red')}</td><td>${btn('Open','review-post','mini-btn')}</td></tr><tr><td>Barista spotlight</td><td>Sara</td><td>${badge('Approved','green')}</td><td>${btn('View','review-post','mini-btn')}</td></tr></table></div><div class="card"><h3>Team</h3><table><tr><td><b>Mohamed</b><br><small>m@acme.com</small></td><td>Owner</td><td>${badge('All brands','purple')}</td></tr><tr><td><b>Sara</b><br><small>s@acme.com</small></td><td>Content Creator</td><td>${badge('Acme Coffee')}</td></tr><tr><td><b>Omar</b><br><small>o@acme.com</small></td><td>Marketing Manager</td><td>${badge('All brands')}</td></tr></table></div></div>`}
function calendar(){let days=['Sun 20','Mon 21','Tue 22','Wed 23','Thu 24','Fri 25','Sat 26'];return head('Social Calendar','Month, week and agenda planning for draft, review, scheduled, publishing, published and failed content.',btn('＋ Schedule content','schedule','primary')+btn('Agenda view','simulate'))+`<div class="calendar">${days.map((d,i)=>`<div class="day"><strong>${d}</strong>${i===1?'<div class="post-chip"><div class="thumb"></div><b>10:00 · Instagram</b><span>Published</span></div>':''}${i===3?'<div class="post-chip"><div class="thumb"></div><b>14:30 · LinkedIn</b><span>Scheduled</span></div><div class="post-chip" style="border-left-color:#d69b00"><b>18:00 · Instagram</b><span>Needs approval</span></div>':''}${i===5?'<div class="post-chip"><div class="thumb"></div><b>20:00 · TikTok</b><span>Scheduled</span></div>':''}</div>`).join('')}</div><div class="section-title"><h3>Selected item</h3></div><div class="card"><div class="connection"><div><h3>Evening Rituals</h3><p>Instagram · Wednesday 23 Sep · 18:00 Asia/Riyadh · Approval required</p></div><div class="actions">${btn('Open content','go-content')}${btn('Reschedule','schedule')}${btn('Cancel','simulate','danger')}</div></div></div>`}
function social(){return head('Social Media Hub','Connect brand-owned social accounts through OAuth, monitor connection health and see publishing results.',btn('＋ Connect account','connect-account','primary'))+`<div class="grid two">${[['IG','Instagram','@acme.coffee','Healthy'],['f','Facebook','Acme Coffee','Healthy'],['in','LinkedIn','Acme Group','Healthy'],['TT','TikTok','@acmecoffee','Reconnect']].map(x=>`<div class="card connection"><div class="platform"><div class="platform-icon">${x[0]}</div><div><h3>${x[1]}</h3><p>${x[2]}</p></div></div><div>${badge(x[3],x[3]==='Healthy'?'green':'amber')} ${btn(x[3]==='Healthy'?'Manage':'Reconnect',x[3]==='Healthy'?'manage-connection':'connect-account','mini-btn')}</div></div>`).join('')}</div><div class="section-title"><h3>Recent publishing</h3></div><div class="card"><table><tr><th>Content</th><th>Platform</th><th>Result</th><th>Published</th><th></th></tr><tr><td>Morning Ritual</td><td>Instagram</td><td>${badge('Published','green')}</td><td>Today 10:00</td><td>${btn('View post','simulate','mini-btn')}</td></tr><tr><td>Hiring announcement</td><td>LinkedIn</td><td>${badge('Published','green')}</td><td>Yesterday</td><td>${btn('View','simulate','mini-btn')}</td></tr></table></div>`}
function analytics(){return head('Smart Analytics','Brand performance with measured totals, trends, comparisons, top posts, platform breakdown and AI explanations grounded in evidence.',btn('Export CSV','export-csv')+btn('Explain with AI','explain-analytics','primary'))+`<div class="grid four">${metric('Impressions','184.2k','+18.4%')}${metric('Reach','96.8k','+11.2%')}${metric('Engagements','12.4k','+21.7%')}${metric('Engagement rate','6.8%','+0.8 pts')}</div><div class="grid two"><div class="card"><h3>Engagement trend</h3><div class="creative-stage" style="min-height:210px"><div><strong>▁▂▃▂▄▅▇</strong><p>Measured trend · last 28 days</p></div></div></div><div class="card"><h3>By platform</h3><table><tr><th>Platform</th><th>Engagements</th><th>Change</th></tr><tr><td>Instagram</td><td>8,420</td><td class="positive">+24%</td></tr><tr><td>TikTok</td><td>2,980</td><td class="positive">+11%</td></tr><tr><td>Facebook</td><td>720</td><td class="negative">-4%</td></tr><tr><td>LinkedIn</td><td>310</td><td class="positive">+8%</td></tr></table></div></div><div class="section-title"><h3>Top content</h3></div><div class="card"><table><tr><th>Post</th><th>Platform</th><th>Reach</th><th>Engagement rate</th></tr><tr><td>How we dial espresso</td><td>Instagram</td><td>21,430</td><td>9.4%</td></tr><tr><td>Inside our Riyadh branch</td><td>TikTok</td><td>18,200</td><td>8.7%</td></tr></table></div>`}
function intelligence(){return head('Marketing Intelligence','Turns measured performance and approved market/competitor context into content gaps, opportunities and recommendations.',btn('Refresh analysis','refresh-intelligence','primary'))+`<div class="grid three"><div class="card"><h3>Content gap</h3><p>Education is 8% of recent output while strategy target is 30%. Educational posts are also above the brand median.</p>${btn('Create ideas','go-content','primary')}</div><div class="card"><h3>Format opportunity</h3><p>Carousels have stronger saves per reach than static posts in the current measured period.</p>${btn('Open evidence','go-analytics')}</div><div class="card"><h3>Competitor context</h3><p>3 competitor notes need review. BrandSpace keeps these as customer-approved context, not inferred facts.</p>${btn('Review competitors','go-brain')}</div></div><div class="section-title"><h3>Recommendations</h3></div><div class="card"><table><tr><th>Recommendation</th><th>Basis</th><th>Action</th></tr><tr><td>Increase educational carousel frequency.</td><td>Strategy gap + measured saves</td><td>${btn('Add to monthly plan','monthly-plan','mini-btn')}</td></tr><tr><td>Test bilingual weekend captions.</td><td>Recent engagement pattern</td><td>${btn('Create test post','go-content','mini-btn')}</td></tr></table></div>`}
function copilot(){return head('AI Copilot','Permission-aware assistant across the workspace. It can read allowed Brand Brain and analytics context, propose actions and execute only what the current user is authorized to do.',btn('New conversation','new-chat'))+`<div class="grid two"><div class="card copilot-box"><h3>Ask BrandSpace</h3><div class="kpi-strip"><button class="pill" data-action="copilot-prompt">Why did engagement increase?</button><button class="pill" data-action="copilot-prompt">Plan next week</button><button class="pill" data-action="copilot-prompt">Create campaign ideas</button></div><div class="chat"><div class="bubble user">What should we post next week?</div><div class="bubble ai">Based on your active strategy and the last 28 days, I’d fill the education gap first: 2 educational carousels, 1 branch-experience Reel and 1 product post. I can create a draft weekly plan.</div><div class="bubble user">Do it.</div><div class="bubble ai"><b>Action preview</b><br>Create 4 content ideas for Acme Coffee and add them to the October monthly plan. No external publishing will happen.</div></div><div class="actions">${btn('Confirm action','confirm-copilot','primary')}${btn('Cancel','simulate')}</div><div class="chat-compose"><input placeholder="Ask about your brand, content or analytics…"><button class="primary" data-action="copilot-send">Send</button></div></div><div class="card"><h3>What Copilot can do</h3><table><tr><td>Read Brand Brain</td><td>${badge('Permission checked','green')}</td></tr><tr><td>Explain analytics</td><td>${badge('Evidence grounded','green')}</td></tr><tr><td>Create drafts & plans</td><td>${badge('Preview first','purple')}</td></tr><tr><td>Change workspace data</td><td>${badge('Permission + confirmation','amber')}</td></tr><tr><td>External actions</td><td>${badge('Human confirmation','amber')}</td></tr></table><p>Copilot re-resolves live permission, brand scope and entitlements before each action.</p></div></div>`}
function automations(){return head('Automations','Build rules as Trigger → Condition → Action. Rules do not store permanent authority; permissions and entitlements are checked again on every run.',btn('＋ New automation','new-automation','primary'))+`<div class="grid two"><div class="card"><h3>Active rules</h3><table><tr><th>Rule</th><th>Status</th><th>Runs</th><th></th></tr><tr><td>When content is approved → notify marketing</td><td>${badge('On','green')}</td><td>24</td><td>${btn('Edit','new-automation','mini-btn')}</td></tr><tr><td>When engagement crosses 8% → notify owner</td><td>${badge('On','green')}</td><td>3</td><td>${btn('Edit','new-automation','mini-btn')}</td></tr><tr><td>Every Monday 09:00 → create planning reminder</td><td>${badge('Off')}</td><td>8</td><td>${btn('Enable','simulate','mini-btn')}</td></tr></table></div><div class="card"><h3>Rule builder</h3><div class="rule"><div class="rule-box"><small>TRIGGER</small><b>Content approved</b></div><span>→</span><div class="rule-box"><small>CONDITION</small><b>Brand = Acme Coffee</b></div><span>→</span><div class="rule-box"><small>ACTION</small><b>Send notification</b></div></div><div class="actions" style="margin-top:12px">${btn('Test rule','test-rule')}${btn('Save rule','save-rule','primary')}</div></div></div><div class="section-title"><h3>Recent runs</h3></div><div class="card"><table><tr><th>Rule</th><th>Started</th><th>Result</th></tr><tr><td>Approval notification</td><td>10:42</td><td>${badge('Completed','green')}</td></tr><tr><td>Metric threshold</td><td>Yesterday</td><td>${badge('Completed','green')}</td></tr></table></div>`}
function notifications(){return head('Notifications','Customer notification center for approvals, publishing, connection health, automations, credits and account events.',btn('Mark all read','mark-read'))+`<div class="card">${[['Approval needed','Weekend coffee carousel is ready for your review.','5 min ago'],['Published','Morning Ritual was published to Instagram.','1 h ago'],['Automation','Engagement crossed 8% for Acme Coffee.','Yesterday'],['Credits','You have used 38% of this cycle’s AI credits.','2 days ago']].map(x=>`<div class="notification"><span class="notification-dot"></span><div><strong>${x[0]}</strong><p>${x[1]}</p><small>${x[2]}</small></div></div>`).join('')}</div><div class="section-title"><h3>Preferences</h3></div><div class="card"><table><tr><th>Event</th><th>In app</th><th>Email</th></tr><tr><td>Approvals</td><td>✓</td><td>✓</td></tr><tr><td>Publishing failures</td><td>✓</td><td>✓</td></tr><tr><td>Low credits</td><td>✓</td><td>✓</td></tr><tr><td>Routine publishing success</td><td>✓</td><td>—</td></tr></table></div>`}
function activity(){return head('Activity Log','Human-readable, filterable history of important workspace actions for accountability and support.',btn('Export activity','export-activity'))+`<div class="card"><div class="timeline"><div class="timeline-item"><strong>Mohamed approved “Morning Ritual”</strong><p>Content · Acme Coffee · 10:21</p></div><div class="timeline-item"><strong>Publishing worker published to Instagram</strong><p>System · Acme Coffee · 10:00</p></div><div class="timeline-item"><strong>Sara updated Brand Brain: Audience</strong><p>Brand Brain · Yesterday 16:42</p></div><div class="timeline-item"><strong>Omar created automation “Approval notification”</strong><p>Automations · 2 days ago</p></div><div class="timeline-item"><strong>Instagram connection refreshed</strong><p>Social Media Hub · 3 days ago</p></div></div></div>`}
function settings(){return head('Settings','Workspace, brands, locale/timezone, security, integrations, retention and data controls.',btn('Save settings','save-settings','primary'))+`<div class="tabs"><button class="tab active">Workspace</button><button class="tab">Brands</button><button class="tab">Security</button><button class="tab">Integrations</button><button class="tab">Data & retention</button></div><div class="grid two"><div class="card"><h3>Workspace</h3><div class="form-grid"><div class="field"><label>Workspace name</label><input value="Acme Group"></div><div class="field"><label>Default locale</label><select><option>English</option><option>Arabic</option></select></div><div class="field"><label>Timezone</label><select><option>Asia/Riyadh</option></select></div><div class="field"><label>Week starts</label><select><option>Sunday</option></select></div></div></div><div class="card"><h3>Brand defaults</h3><div class="field"><label>Arabic dialect</label><select><option>Saudi / Gulf</option><option>Modern Standard Arabic</option><option>Egyptian</option><option>Levantine</option></select></div><div class="field"><label>Approval policy</label><select><option>Require approval before scheduling</option><option>Approval optional</option></select></div><div class="field"><label>Self approval</label><select><option>Denied</option><option>Allowed for selected roles</option></select></div></div></div>`}
function billing(){return head('Billing & Usage','Plan, subscription, invoices, resource limits, AI credits and credit packs. Customers see credits — provider token pricing stays internal.',btn('Manage plan','manage-plan','primary')+btn('Buy credits','buy-credits'))+`<div class="grid three">${metric('Current plan','Growth','Renews 1 Oct')}${metric('AI credits','8,420','of 13,500 available')}${metric('Storage','3.8 GB','of 25 GB')}</div><div class="grid two"><div class="card"><h3>AI credit usage</h3><div class="usage-bar"><span style="width:38%"></span></div><p>5,080 credits used this cycle. BrandSpace reserves credits before an AI action and settles actual usage after completion.</p><table><tr><td>Content generation</td><td>2,140</td></tr><tr><td>Copilot</td><td>1,390</td></tr><tr><td>AI Strategy</td><td>780</td></tr><tr><td>Creative generation</td><td>770</td></tr></table></div><div class="card"><h3>Limits</h3><table><tr><td>Brands</td><td>3 / 5</td></tr><tr><td>Members</td><td>6 / 10</td></tr><tr><td>Connected accounts</td><td>4 / 10</td></tr><tr><td>Scheduled posts</td><td>18 / monthly allowance</td></tr></table><div class="actions">${btn('View invoices','simulate')}${btn('Payment method','simulate')}</div></div></div>`}
const pages={'command-center':commandCenter,'brand-center':brandCenter,'brand-brain':brandBrain,'strategy':strategy,'campaigns':campaigns,'content':contentStudio,'creative':creative,'assets':assets,'approvals':approvals,'calendar':calendar,'social':social,'analytics':analytics,'intelligence':intelligence,'copilot':copilot,'automations':automations,'notifications':notifications,'activity':activity,'settings':settings,'billing':billing};
function render(id=state.page){state.page=id;const mod=modules.find(m=>m[1]===id);title.textContent=mod?mod[3]:'BrandSpace';eyebrow.textContent=mod?mod[0]:'CUSTOMER DASHBOARD';content.innerHTML=(pages[id]||commandCenter)();document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===id));history.replaceState(null,'','#'+id);document.getElementById('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});}
function mediaModal(){openModal('Add media',`<div class="grid three"><button class="card" data-action="upload-and-use"><h3>↑ Upload new</h3><p>Upload a new brand-owned image or video. It becomes an Asset after validation.</p></button><button class="card" data-action="choose-and-use"><h3>▧ Choose from Assets</h3><p>Select an existing approved asset from the brand library.</p></button><button class="card" data-action="create-and-use"><h3>✦ Create with AI</h3><p>Open AI Creative Studio, generate an on-brand image, save it as an Asset and use it here.</p></button></div>`)}
function scheduleModal(){openModal('Schedule content',`<div class="form-grid"><div class="field"><label>Date</label><input type="date" value="2026-09-23"></div><div class="field"><label>Local time</label><input type="time" value="18:00"></div><div class="field"><label>Timezone</label><select><option>Asia/Riyadh</option></select></div><div class="field"><label>Platforms</label><select><option>Instagram + Facebook</option></select></div></div><p class="helper">Approval policy is checked before scheduling and again before external publishing.</p><div class="actions">${btn('Schedule','confirm-schedule','primary')}${btn('Cancel','close-modal')}</div>`)}
function automationModal(){openModal('Create automation',`<div class="form-grid"><div class="field"><label>Trigger</label><select><option>Content approved</option><option>Content published</option><option>Scheduled time</option><option>Metric threshold crossed</option></select></div><div class="field"><label>Condition field</label><select><option>Brand</option><option>Provider</option><option>Metric value</option></select></div><div class="field"><label>Operator</label><select><option>equals</option></select></div><div class="field"><label>Value</label><input value="Acme Coffee"></div><div class="field full"><label>Action</label><select><option>Send notification</option></select></div></div><div class="actions">${btn('Save automation','save-automation-modal','primary')}${btn('Cancel','close-modal')}</div>`)}
function reviewModal(){openModal('Review content',`<div class="social-preview"><div class="preview-head"><span class="preview-avatar"></span><b>acme.coffee</b></div><div class="preview-media">WEEKEND<br>RITUALS</div><div class="preview-copy">A slower weekend starts here. Thoughtful coffee, warm light and a little more time.</div></div><div class="field" style="margin-top:12px"><label>Reviewer reason / note</label><textarea placeholder="Optional note or required reason when requesting changes"></textarea></div><div class="actions">${btn('Approve','approve-post','primary')}${btn('Request changes','request-changes','danger')}${btn('Close','close-modal')}</div>`)}
function genericForm(name,fields){openModal(name,`<div class="form-grid">${fields.map(f=>`<div class="field ${f.full?'full':''}"><label>${f.label}</label>${f.area?`<textarea>${f.value||''}</textarea>`:`<input value="${esc(f.value||'')}">`}</div>`).join('')}</div><div class="actions">${btn('Save','generic-save','primary')}${btn('Cancel','close-modal')}</div>`)}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){render(p.dataset.page);return}const a=e.target.closest('[data-action]');if(!a)return;const x=a.dataset.action;const go={"go-brain":'brand-brain',"go-assets":'assets',"go-creative":'creative',"go-content":'content',"go-approvals":'approvals',"go-social":'social',"go-billing":'billing',"go-settings":'settings',"go-campaigns":'campaigns',"go-analytics":'analytics',"go-intelligence":'intelligence'};if(go[x]){render(go[x]);return}if(x==='toggle-sidebar'){document.getElementById('sidebar').classList.toggle('open');return}if(x==='close-modal'){closeModal();return}if(x==='show-cycle'){cycleModal();return}if(x==='new-post'){render('content');return}if(x==='add-media'){mediaModal();return}if(['upload-and-use','choose-and-use'].includes(x)){state.media=true;closeModal();render('content');toastMsg('Media attached to this content variant.');return}if(x==='create-and-use'){closeModal();render('creative');toastMsg('Generate a visual, then use it in the post.');return}if(x==='remove-media'){state.media=false;render('content');return}if(x==='generate-copy'){state.caption='Evenings feel different when the details slow down with you. Settle in, take your time, and let the coffee do the rest. #AcmeCoffee #EveningRitual';state.credits-=38;render('content');toastMsg('Grounded channel variants generated · 38 credits settled.');return}if(x==='estimate'){toastMsg('Estimated generation: 35–45 AI credits. No credits charged.');return}if(x==='estimate-creative'){toastMsg('Estimated 4-image generation: 160–220 AI credits.');return}if(x==='generate-visual'){state.generated=true;state.credits-=188;render('creative');toastMsg('4 visual options generated · 188 credits settled.');return}if(x==='save-generated'){toastMsg('Generated image saved to Asset Library with AI provenance.');return}if(x==='use-generated'){state.media=true;render('content');toastMsg('Generated Asset attached to the post.');return}if(x==='resize-generated'){toastMsg('Platform sizes prepared from the selected creative.');return}if(x==='choose-assets'){render('assets');return}if(x==='use-asset'){state.media=true;render('content');toastMsg('Asset attached to the draft.');return}if(x==='schedule'){scheduleModal();return}if(x==='confirm-schedule'){closeModal();render('calendar');toastMsg('Content scheduled in workspace local time.');return}if(x==='review-post'){reviewModal();return}if(x==='approve-post'){closeModal();toastMsg('Content approved. It can now be scheduled according to policy.');return}if(x==='request-changes'){closeModal();toastMsg('Changes requested and creator notified.');return}if(x==='new-automation'){automationModal();return}if(x==='save-automation-modal'){closeModal();toastMsg('Automation saved. Live authority will be checked on every run.');return}if(x==='connect-account'){openModal('Connect social account','<p>This prototype would redirect the customer to the provider OAuth flow. BrandSpace never asks for the social password.</p><div class="actions"><button class="primary" data-action="oauth-done">Continue to provider</button><button class="ghost" data-action="close-modal">Cancel</button></div>');return}if(x==='oauth-done'){closeModal();toastMsg('Prototype: OAuth completed and target account selected.');return}if(x==='new-campaign'){genericForm('New campaign',[{label:'Campaign name',value:'October Rituals'},{label:'Goal',value:'Increase repeat visits'},{label:'Start date',value:'2026-10-01'},{label:'End date',value:'2026-10-31'},{label:'Channels',value:'Instagram, TikTok, Facebook',full:true}]);return}if(x==='add-knowledge'){genericForm('Add Brand Brain knowledge',[{label:'Knowledge type',value:'Audience'},{label:'Title',value:'Primary audience'},{label:'Approved knowledge',value:'Urban professionals and students in Riyadh seeking quality coffee without formality.',area:true,full:true}]);return}if(x==='invite-member'){genericForm('Invite team member',[{label:'Email',value:'new@acme.com'},{label:'Role',value:'Content Creator'},{label:'Brand scope',value:'Acme Coffee',full:true}]);return}if(x==='generate-strategy'){state.credits-=85;toastMsg('Strategy refreshed from approved Brand Brain + measured context · 85 credits.');return}if(x==='monthly-plan'){toastMsg('Monthly planning flow opened from the active strategy.');return}if(x==='explain-analytics'){state.credits-=24;openModal('AI explanation','<p><b>Measured explanation:</b> engagement increased primarily in posts categorized as educational and branch-experience content during the selected period. The explanation is constrained to cited workspace evidence.</p><div class="actions"><button class="primary" data-action="close-modal">Done</button></div>');return}if(x==='confirm-copilot'){state.credits-=31;toastMsg('Copilot action confirmed: 4 draft ideas added to the monthly plan.');return}if(x==='buy-credits'){openModal('Buy AI credits','<p>Select a credit pack. Purchased credits are added to the workspace wallet and consumed according to the credit policy.</p><div class="grid three"><button class="card" data-action="generic-save"><b>5k credits</b></button><button class="card" data-action="generic-save"><b>15k credits</b></button><button class="card" data-action="generic-save"><b>50k credits</b></button></div>');return}if(x==='generic-save'){closeModal();toastMsg('Prototype action saved.');return}if(['shorter','tone','hashtags','translate'].includes(x)){toastMsg('AI edit applied to this channel variant.');return}if(x==='copilot-send'||x==='copilot-prompt'){toastMsg('Prototype: Copilot would answer using permitted workspace context.');return}toastMsg('Prototype interaction: '+x.replaceAll('-',' ')+'.');});
document.getElementById('brand-switcher').addEventListener('change',e=>{state.brand=e.target.value;toastMsg(`Active brand changed to ${state.brand}.`);render(state.page)});modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});buildNav();render(location.hash.replace('#','')||'command-center');
